import { moduleMetadata } from '@storybook/angular';
import { NavbarComponent } from './navbar.component';
import { ButtonComponent } from '../button/button.component';
import { CommonModule } from '@angular/common';
const meta = {
    title: 'Components/Navbar',
    component: NavbarComponent,
    decorators: [
        moduleMetadata({
            imports: [CommonModule, ButtonComponent],
        }),
    ],
    tags: ['autodocs'],
};
export default meta;
export const Primary = {
    args: {
        isAboutUsActive: false,
        isOurWorksActive: false,
    },
    argTypes: {
        isAboutUsActive: { control: 'boolean' },
        isOurWorksActive: { control: 'boolean' },
    },
};
export const AboutUsActive = {
    args: {
        isAboutUsActive: true,
        isOurWorksActive: false,
        isJoinUsActive: false,
    },
};
export const OurWorksActive = {
    args: {
        isAboutUsActive: false,
        isOurWorksActive: true,
        isJoinUsActive: false,
    },
};
export const JoinUsActive = {
    args: {
        isAboutUsActive: false,
        isOurWorksActive: false,
        isJoinUsActive: true,
    },
};
